package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
)

func main() {
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	ctx, cancel := context.WithCancel(context.Background())
	req = req.WithContext(ctx)
	cancel()
	if req.Context().Err() == context.Canceled {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

